# M1: Gompertz with time-varying rate and K: y = P*(a+b*t+c*sin(wt)+d*cos(wt)) - e*P*lnP + f*P^2
def M1(p):
    a,b,c,d,e,f,w=p[:7]
    return P*(a+b*t+c*np.sin(w*t)+d*np.cos(w*t)) - e*P*np.log(P)+f*P**2
# M2: logistic with time-varying K: y = r(t)*P*(1-P/K(t)), K=1/(a+b sin+ c cos), r=const+ sin
def M2(p):
    r0,r1,r2,k0,k1,k2,w=p[:7]
    r=r0+r1*np.sin(w*t)+r2*t
    q=k0+k1*np.sin(w*t)+k2*np.cos(w*t)
    return r*P - P**2*q
# M3: y = a P - b P lnP + (c + d sin + e cos) P^2 + g sin P + h cos P + t terms
