L=np.log(P)
def feats(w,names):
    s=np.sin(w*t); c=np.cos(w*t)
    d={'1':np.ones_like(t),'P':P,'t':t,'PL':P*L,'P2':P**2,'Ps':P*s,'Pc':P*c,'s':s,'c':c,'t2':t**2,'Pt2':P*t**2,
       'PLs':P*L*s,'PLc':P*L*c,'PLt':P*L*t,'tPL':t*P*L,'P2s':P**2*s,'P2c':P**2*c,'Pts':P*t*s,'Ptc':P*t*c,'Pt':P*t}
    return np.column_stack([d[n] for n in names])
def err(w,names):
    A=feats(w,names); c,_,_,_=np.linalg.lstsq(A,y,rcond=None); r=y-A@c
    return np.mean(r**2)/np.var(y)
